<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../app/helpers.php';require_login();require_role('admin','staff');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$supplier=(int)($_POST['supplier_id']??0);$product=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$cost=(float)($_POST['unit_cost']??0);if($supplier<1||$product<1||$qty<1||$cost<0){flash('danger','Vui lòng kiểm tra dữ liệu nhập kho.');redirect('/purchases.php');}
try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT id FROM products WHERE id=? AND is_active=1 FOR UPDATE');$st->execute([$product]);if(!$st->fetch())throw new RuntimeException('Sản phẩm không tồn tại.');$st=$pdo->prepare('INSERT INTO purchase_orders(purchase_code,supplier_id,created_by,total_amount) VALUES(?,?,?,?)');$code='PO-'.date('ymd-His').'-'.random_int(100,999);$st->execute([$code,$supplier,current_user()['id'],$qty*$cost]);$purchaseId=(int)$pdo->lastInsertId();$st=$pdo->prepare('INSERT INTO purchase_order_items(purchase_order_id,product_id,quantity,unit_cost) VALUES(?,?,?,?)');$st->execute([$purchaseId,$product,$qty,$cost]);$st=$pdo->prepare('UPDATE products SET stock_qty=stock_qty+?,cost_price=? WHERE id=?');$st->execute([$qty,$cost,$product]);$st=$pdo->prepare("INSERT INTO stock_movements(product_id,movement_type,quantity,reference_type,reference_id,note,created_by) VALUES(?,'in',?,'purchase',?,?,?)");$st->execute([$product,$qty,$purchaseId,'Nhập kho '.$code,current_user()['id']]);$pdo->commit();flash('success',"Đã nhập kho thành công: $code");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Không thể nhập kho: '.$e->getMessage());}redirect('/purchases.php');}
$products=$pdo->query('SELECT id,sku,name,cost_price,stock_qty FROM products WHERE is_active=1 ORDER BY name')->fetchAll();$suppliers=$pdo->query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT po.purchase_code,po.created_at,po.total_amount,s.name supplier,u.full_name FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id JOIN users u ON u.id=po.created_by ORDER BY po.id DESC LIMIT 30')->fetchAll();$pageTitle='Nhập kho';require __DIR__.'/../app/layout/header.php';?>
<div class="page-heading mb-3"><div><h1 class="h3">Nhập kho</h1><p class="text-secondary mb-0">Tạo phiếu nhập, cập nhật tồn kho và ghi lịch sử giao dịch.</p></div></div><div class="row g-4"><div class="col-12 col-xl-4"><div class="card"><div class="card-body"><h2 class="h5">Phiếu nhập mới</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Nhà cung cấp</label><select name="supplier_id" class="form-select" required><option value="">Chọn nhà cung cấp</option><?php foreach($suppliers as $s):?><option value="<?=(int)$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Sản phẩm</label><select name="product_id" class="form-select" required><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['sku'].' · '.$p['name'].' (tồn '.$p['stock_qty'].')')?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Số lượng</label><input type="number" min="1" name="quantity" class="form-control" required></div><div class="mb-3"><label class="form-label">Đơn giá nhập</label><input type="number" min="0" step="1000" name="unit_cost" class="form-control" required></div><button class="btn btn-primary">Tạo phiếu nhập</button></form></div></div></div><div class="col-12 col-xl-8"><div class="card"><div class="card-body"><h2 class="h5 mb-3">Phiếu nhập gần đây</h2><div class="table-responsive"><table class="table"><thead><tr><th>Mã phiếu</th><th>Nhà cung cấp</th><th>Ngày nhập</th><th>Tổng tiền</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['purchase_code'])?></td><td><?=e($r['supplier'])?></td><td><?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></td><td><?=money($r['total_amount'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/../app/layout/footer.php';?>
